  "agm": {label:"Jahreshauptversammlung",gender:"die",plural:"Jahreshauptversammlungen", ex5:[{t:1,s:"Die Jahreshauptversammlung findet nächste Woche statt."},{t:2,s:"Alle Mitarbeiter sollen an der Jahreshauptversammlung teilnehmen."},{t:3,s:"Wir haben das Budget auf der Jahreshauptversammlung besprochen."},{t:4,s:"Die Jahreshauptversammlung dauerte drei Stunden."},{t:5,s:"Er hielt eine Rede bei der Jahreshauptversammlung."}]},
  "agnes": {label:"Agnes",gender:"",plural:"—", ex5:[{t:1,s:"Agnes ist meine beste Schulfreundin."},{t:2,s:"Ich bin mit Agnes in die Bibliothek gegangen."},{t:3,s:"Agnes hat mich zu ihrer Geburtstagsfeier eingeladen."},{t:4,s:"Ich treffe mich heute mit Agnes."},{t:5,s:"Agnes wohnt in der Nähe von Berlin."}]},
  "agnostic": {label:"Agnostiker",gender:"der",plural:"Agnostiker", ex5:[{t:1,s:"Er bezeichnet sich selbst als Agnostiker."},{t:2,s:"Sie vertritt eine agnostische Sichtweise zum Leben nach dem Tod."},{t:3,s:"Als Agnostiker möchte er keine voreiligen Schlüsse ziehen."},{t:4,s:"Ein Agnostiker zweifelt an der Erkennbarkeit Gottes."},{t:5,s:"Das ist ein agnostischer Ansatz für dieses Problem."}]},
