  "agreement": {label:"Vereinbarung",gender:"die",plural:"Vereinbarungen", ex5:[{t:1,s:"Die Vereinbarung gilt."},{t:2,s:"Die Vereinbarung ist fair."},{t:3,s:"Wir haben die Vereinbarung unterzeichnet."},{t:4,s:"Wir müssen die Vereinbarung einhalten."},{t:5,s:"Es gibt eine neue Vereinbarung zwischen uns."}]},
  "agreements": {label:"Vereinbarungen",gender:"die",plural:"Vereinbarungen", ex5:[{t:1,s:"Die Vereinbarungen haben sich vervielfacht."},{t:2,s:"Die Vereinbarungen sind unterzeichnet."},{t:3,s:"Wir haben die Vereinbarungen überprüft."},{t:4,s:"Alle Vereinbarungen wurden eingehalten."},{t:5,s:"Er hat die Vereinbarungen genau gelesen."}]},
  "agrees": {label:"stimmt zu",gender:"",plural:"—", ex5:[{t:1,s:"Sie stimmt zu."},{t:2,s:"Der Experte stimmt zu."},{t:3,s:"Er stimmt dem Punkt zu."},{t:4,s:"Mein Vater stimmt meiner Idee zu."},{t:5,s:"Jeder stimmt dieser Meinung zu."}]},
