  "antichrist": {label:"Antichrist",gender:"der",plural:"Antichristen", ex5:[{t:1,s:"Der Roman erzählt eine Geschichte über den Antichrist."},{t:2,s:"Einige Menschen glauben, dass der Antichrist bald erscheint."},{t:3,s:"Die Figur im Film wurde als Antichrist dargestellt."},{t:4,s:"In alten Schriften wird der Antichrist erwähnt."},{t:5,s:"Er wurde oft als der Antichrist bezeichnet."}]},
  "anticipate": {label:"vorhersehen",gender:"",plural:"—", ex5:[{t:1,s:"Wir können die Folgen kaum vorhersehen."},{t:2,s:"Man muss Probleme frühzeitig vorhersehen."},{t:3,s:"Können Sie die Reaktion des Marktes vorhersehen?"},{t:4,s:"Er konnte den Ausgang des Spiels vorhersehen."},{t:5,s:"Es ist schwer, alle Schwierigkeiten vorherzusehen."}]},
  "anticipated": {label:"erwartet",gender:"",plural:"—", ex5:[{t:1,s:"Das Ergebnis war so erwartet worden."},{t:2,s:"Die Ankunft wurde mit Spannung erwartet."},{t:3,s:"Er hat das erwartete Ziel erreicht."},{t:4,s:"Die Nachricht war nicht wie erwartet."},{t:5,s:"Alles lief wie erwartet."}]},
  "anticipates": {label:"erwartet",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma erwartet höhere Gewinne in diesem Jahr."},{t:2,s:"Jeder erwartet eine großartige Vorstellung."},{t:3,s:"Sie erwartet, dass das Projekt bis Freitag fertig ist."},{t:4,s:"Er erwartet heute noch einen Anruf."},{t:5,s:"Die Regierung erwartet eine Änderung der Lage."}]},
  "anticipating": {label:"erwartend",gender:"",plural:"—", ex5:[{t:1,s:"Wir sind erwartend gestimmt für das Konzert."},{t:2,s:"Sie schaute erwartend auf die Tür."},{t:3,s:"Die Kinder warten erwartend auf die Geschenke."},{t:4,s:"Er blickte erwartend in die Runde."},{t:5,s:"Wir sehen dem Treffen erwartend entgegen."}]},
