  "antithesis": {label:"Antithese",gender:"die",plural:"Antithesen", ex5:[{t:1,s:"Ihre Ruhe war die Antithese zu seiner Panik."},{t:2,s:"Das neue Design ist die Antithese zum alten."},{t:3,s:"Grausamkeit ist die Antithese zur Freundlichkeit."},{t:4,s:"Diese Theorie bildet die Antithese zu seinem Modell."},{t:5,s:"Seine Handlung war die Antithese zu seinen Worten."}]},
  "antithetical": {label:"gegensätzlich",gender:"",plural:"—", ex5:[{t:1,s:"Seine Handlungen waren gegensätzlich zu seinen erklärten Werten."},{t:2,s:"Krieg ist zum Ziel des Weltfriedens gegensätzlich."},{t:3,s:"Wissenschaftlicher Fortschritt ist oft gegensätzlich zu alten Aberglauben."},{t:4,s:"Die Meinungen der beiden sind völlig gegensätzlich."},{t:5,s:"Das Ergebnis ist gegensätzlich zu unseren Erwartungen."}]},
  "antitrust": {label:"kartellrechtlich",gender:"",plural:"—", ex5:[{t:1,s:"Es gelten kartellrechtliche Bestimmungen."},{t:2,s:"Der Fall ist kartellrechtlich relevant."},{t:3,s:"Sie haben eine kartellrechtliche Klage eingereicht."},{t:4,s:"Das Unternehmen verstößt gegen kartellrechtliche Regeln."},{t:5,s:"Die Behörde prüft den Vorgang kartellrechtlich."}]},
  "antiviral": {label:"antiviral",gender:"",plural:"—", ex5:[{t:1,s:"Der Arzt verschrieb ein antivirales Medikament gegen die Grippe."},{t:2,s:"Wissenschaftler entwickeln ein neues antivirales Mittel."},{t:3,s:"Diese Pflanze ist für ihre antivirale Wirkung bekannt."},{t:4,s:"Die antivirale Therapie schlug gut an."},{t:5,s:"Es gibt viele antivirale Wirkstoffe in der Natur."}]},
  "antivirus": {label:"Antivirenprogramm",gender:"das",plural:"Antivirenprogramme", ex5:[{t:1,s:"Installieren Sie unbedingt ein Antivirenprogramm auf Ihrem neuen Computer."},{t:2,s:"Das Antivirenprogramm erkannte während des Scans eine Bedrohung."},{t:3,s:"Ich muss mein Antivirenprogramm aktualisieren, um geschützt zu sein."},{t:4,s:"Ein gutes Antivirenprogramm ist heute unerlässlich."},{t:5,s:"Das Antivirenprogramm läuft im Hintergrund."}]},
  "antiwar": {label:"antikriegs-",gender:"",plural:"—", ex5:[{t:1,s:"Tausende Studenten nahmen an der Antikriegs-Demonstration teil."},{t:2,s:"Sie schrieb während ihrer Studienzeit ein schönes Antikriegs-Lied."},{t:3,s:"Der Autor ist für seine kraftvollen Antikriegs-Romane bekannt."},{t:4,s:"Das ist ein wichtiger Antikriegs-Film."},{t:5,s:"Es gab eine große Antikriegs-Bewegung im Land."}]},
  "antler": {label:"Geweih",gender:"das",plural:"Geweihe", ex5:[{t:1,s:"Der Hirsch warf im späten Winter sein Geweih ab."},{t:2,s:"Der männliche Hirsch nutzt sein großes Geweih, um um Partner zu kämpfen."},{t:3,s:"Wir fanden ein abgebrochenes Stück eines Geweihs im Wald."},{t:4,s:"Das Geweih des Hirsches ist beeindruckend groß."},{t:5,s:"Im Frühling beginnt das Geweih wieder zu wachsen."}]},
  "antlers": {label:"Geweih",gender:"das",plural:"Geweihe", ex5:[{t:1,s:"Der männliche Hirsch hat ein großes, beeindruckendes Geweih."},{t:2,s:"Wir sahen einen Hirsch mit einem spitzen Geweih im Wald."},{t:3,s:"Das Geweih fiel dem Hirsch im Winter ab."},{t:4,s:"Die Geweihe der Hirsche sind im Herbst besonders prächtig."},{t:5,s:"Er beobachtete den Hirsch, wie er sein Geweih am Baum rieb."}]},
  "antoine": {label:"Antoine",gender:"",plural:"—", ex5:[{t:1,s:"Antoine ist mein bester Freund aus Frankreich."},{t:2,s:"Ich habe Antoine heute Morgen in der Bibliothek getroffen."},{t:3,s:"Antoine hat beschlossen, Musik in Paris zu studieren."},{t:4,s:"Hast du Antoine gestern gesehen?"},{t:5,s:"Antoine kommt am Wochenende zu Besuch."}]},
