  "anwar": {label:"Anwar",gender:"",plural:"—", ex5:[{t:1,s:"Anwar plant, nächsten Monat seine Familie zu besuchen."},{t:2,s:"Ich habe Anwar gestern in der Bibliothek getroffen."},{t:3,s:"Anwar ist der beste Schüler in unserem naturwissenschaftlichen Kurs."},{t:4,s:"Anwar lernt sehr fleißig für die Prüfung."},{t:5,s:"Ich habe mich gestern mit Anwar unterhalten."}]},
  "anxieties": {label:"Ängste",gender:"die",plural:"Ängste", ex5:[{t:1,s:"Das Gespräch mit einem Freund kann helfen, Ängste abzubauen."},{t:2,s:"Viele Schüler haben Ängste vor den Abschlussprüfungen."},{t:3,s:"Sie äußerte ihre tiefen Ängste bezüglich der Zukunft."},{t:4,s:"Man sollte seine Ängste nicht einfach ignorieren."},{t:5,s:"Er sprach offen über seine Ängste."}]},
