  "aural": {label:"akustisch",gender:"",plural:"—", ex5:[{t:1,s:"Der Test enthält einen akustisch orientierten Teil zur Verständnisprüfung."},{t:2,s:"Sie besitzt eine sehr feine akustische Wahrnehmung."},{t:3,s:"Akustische Signale warnen die Arbeiter vor Gefahren."},{t:4,s:"Das Gerät reagiert auf akustische Reize."},{t:5,s:"Die akustische Qualität im Raum ist hervorragend."}]},
  "aurora": {label:"Polarlicht",gender:"das",plural:"Polarlichter", ex5:[{t:1,s:"Wir sind nach Island gereist, um das Polarlicht zu sehen."},{t:2,s:"Das Polarlicht wirkte wie tanzendes grünes Licht am Himmel."},{t:3,s:"Ein Polarlicht zu sehen, steht ganz oben auf meiner Wunschliste."},{t:4,s:"In der Nacht leuchtete ein prächtiges Polarlicht."},{t:5,s:"Das Polarlicht ist ein faszinierendes Naturschauspiel."}]},
  "auspices": {label:"Schirmherrschaft",gender:"die",plural:"Schirmherrschaften", ex5:[{t:1,s:"Die Veranstaltung fand unter der Schirmherrschaft des Bürgermeisters statt."},{t:2,s:"Wir arbeiteten unter ihrer großzügigen Schirmherrschaft."},{t:3,s:"Das Projekt steht unter der Schirmherrschaft der Universität."},{t:4,s:"Dank der Schirmherrschaft konnte die Organisation wachsen."},{t:5,s:"Er übernahm die Schirmherrschaft für das Wohltätigkeitsprojekt."}]},
  "auspicious": {label:"verheißungsvoll",gender:"",plural:"—", ex5:[{t:1,s:"Sie wählten einen verheißungsvollen Tag für ihre Hochzeit."},{t:2,s:"Das Projekt hatte einen verheißungsvollen Start."},{t:3,s:"Ein klarer Himmel war ein verheißungsvolles Zeichen."},{t:4,s:"Es war ein sehr verheißungsvoller Beginn für unsere Partnerschaft."},{t:5,s:"Die Umstände erschienen uns in diesem Moment verheißungsvoll."}]},
  "aussie": {label:"Australier",gender:"der",plural:"Australier", ex5:[{t:1,s:"Er ist ein freundlicher Australier, den ich auf meiner Reise traf."},{t:2,s:"Mein Lehrer ist ein Australier, der das Surfen liebt."},{t:3,s:"Viele Australier verbringen ihre Freizeit gerne im Freien."},{t:4,s:"Ich habe mich mit einem netten Australier unterhalten."},{t:5,s:"Der Australier zeigte mir den Weg zum Strand."}]},
  "aussies": {label:"Australier",gender:"die",plural:"Australier", ex5:[{t:1,s:"Viele Australier gehen am Wochenende gerne surfen."},{t:2,s:"Ich habe auf meiner Reise durch Europa einige nette Australier kennengelernt."},{t:3,s:"Australier sind für ihre entspannte Lebensart bekannt."},{t:4,s:"Die Australier, die ich traf, waren sehr hilfsbereit."},{t:5,s:"Australier lieben es, Zeit in der Natur zu verbringen."}]},
  "austen": {label:"Austen",gender:"",plural:"—", ex5:[{t:1,s:"Jane Austen gehört zu den berühmtesten britischen Romanautoren."},{t:2,s:"Ich lese gerade einen Roman von Jane Austen."},{t:3,s:"Viele Filme basieren auf den klassischen Büchern von Austen."},{t:4,s:"Wir haben im Literaturkurs die Werke von Austen besprochen."},{t:5,s:"Der Stil von Austen ist weltweit bekannt und geschätzt."}]},
  "austere": {label:"schlicht",gender:"",plural:"—", ex5:[{t:1,s:"Der Raum ist sehr schlicht eingerichtet."},{t:2,s:"Sein Schreibstil ist schlicht und direkt."},{t:3,s:"Wir führten ein schlichtes Leben auf dem Land."},{t:4,s:"Die Ausstattung der Wohnung ist bewusst schlicht gehalten."},{t:5,s:"Ein schlichtes Design ist oft zeitlos."}]},
