  "autobiography": {label:"Autobiografie",gender:"die",plural:"Autobiografien", ex5:[{t:1,s:"Er hat eine ehrliche Autobiografie geschrieben."},{t:2,s:"Ihre Autobiografie wurde ein Bestseller."},{t:3,s:"Die Autobiografie umfasst einen Zeitraum von fünfzig Jahren."},{t:4,s:"Ich lese gerade eine interessante Autobiografie."},{t:5,s:"Die Autobiografie gibt Einblicke in sein Leben."}]},
