  "azimuth": {label:"Azimut",gender:"der",plural:"Azimute", ex5:[{t:1,s:"Der Navigator berechnete das Azimut für den Kurs."},{t:2,s:"Das Azimut der Sonne ändert sich im Tagesverlauf."},{t:3,s:"Wir stellten das Teleskop auf das richtige Azimut ein."},{t:4,s:"Das Azimut ist wichtig für die Orientierung."},{t:5,s:"Man muss das Azimut genau bestimmen."}]},
  "aziz": {label:"Aziz",gender:"der",plural:"—", ex5:[{t:1,s:"Ich habe auf der Konferenz einen freundlichen Mann namens Aziz getroffen."},{t:2,s:"Aziz plant, nächsten Sommer nach Korea zu reisen."},{t:3,s:"Könntest du Aziz bitte sagen, dass ich mich verspäte?"},{t:4,s:"Aziz ist ein sehr guter Freund von mir."},{t:5,s:"Ich habe gestern mit Aziz telefoniert."}]},
  "azores": {label:"Azoren",gender:"die",plural:"Azoren", ex5:[{t:1,s:"Sie planen eine Sommerreise auf die Azoren."},{t:2,s:"Die Azoren sind für ihre beeindruckenden Vulkanlandschaften bekannt."},{t:3,s:"Wir haben eine Bootstour um die Inseln der Azoren gemacht."},{t:4,s:"Die Azoren sind ein tolles Reiseziel."},{t:5,s:"Auf den Azoren kann man wunderbar wandern."}]},
  "aztec": {label:"Azteken",gender:"die",plural:"Azteken", ex5:[{t:1,s:"Die Zivilisation der Azteken entstand im alten Mexiko."},{t:2,s:"Er liest gerade ein Buch über die Geschichte der Azteken."},{t:3,s:"Die Azteken erbauten beeindruckende Pyramiden aus Stein."},{t:4,s:"Die Kultur der Azteken ist sehr faszinierend."},{t:5,s:"Man kann viel über die Azteken lernen."}]},
  "azure": {label:"azurblau",gender:"",plural:"—", ex5:[{t:1,s:"Wir schauten in den weiten azurblauen Himmel."},{t:2,s:"Das Meerwasser hatte einen atemberaubenden azurblauen Farbton."},{t:3,s:"Sie träumte davon, auf dem azurblauen Mittelmeer zu segeln."},{t:4,s:"Die Blumen leuchten in einem schönen Azurblau."},{t:5,s:"Das azurblaue Wasser sieht sehr erfrischend aus."}]},
  "baa": {label:"mäh",gender:"",plural:"—", ex5:[{t:1,s:"Das kleine Lamm machte mäh zu seiner Mutter."},{t:2,s:"Ich hörte ein lautes Mäh von der Weide."},{t:3,s:"Jedes Mal, wenn sich das Schaf bewegte, machte es ein leises Mäh."},{t:4,s:"Das Schaf ruft mäh in den Stall."},{t:5,s:"Ein fröhliches Mäh kam von der Wiese."}]},
  "baba": {label:"Oma",gender:"die",plural:"Omas", ex5:[{t:1,s:"Oma hat uns vor dem Schlafengehen eine Geschichte erzählt."},{t:2,s:"Ich liebe es, am Wochenende meine Oma zu besuchen."},{t:3,s:"Oma hat mir ein kleines Geschenk zum Geburtstag gegeben."},{t:4,s:"Meine Oma backt den besten Kuchen der Welt."},{t:5,s:"Ich rufe meine Oma heute Abend an."}]},
  "babble": {label:"lallen",gender:"",plural:"—", ex5:[{t:1,s:"Das Baby fing an, fröhlich in seinem Bettchen zu lallen."},{t:2,s:"Er neigt dazu, zu lallen, wenn er nervös ist."},{t:3,s:"Ich konnte sein Lallen kaum verstehen."},{t:4,s:"Hör auf zu lallen und sprich deutlich."},{t:5,s:"Betrunkene fangen oft an zu lallen."}]},
  "babbling": {label:"Geplapper",gender:"das",plural:"—", ex5:[{t:1,s:"Das Baby lag im Bett und gab ein fröhliches Geplapper von sich."},{t:2,s:"Er war so nervös, dass er nur noch wirres Geplapper hervorbrachte."},{t:3,s:"Man konnte das sanfte Geplapper des kleinen Bachs hören."},{t:4,s:"Das Geplapper der Kinder erfüllte den ganzen Raum."},{t:5,s:"Ihr ständiges Geplapper lenkt mich bei der Arbeit ab."}]},
  "babel": {label:"Babel",gender:"das",plural:"—", ex5:[{t:1,s:"Die Geschichte vom Turm zu Babel ist faszinierend."},{t:2,s:"Die Konferenz fühlte sich wie ein modernes Babel der Sprachen an."},{t:3,s:"Sie versuchten, ein neues Babel mitten in der Stadt zu errichten."},{t:4,s:"Das Chaos erinnerte an den Turmbau zu Babel."},{t:5,s:"Die Welt wirkt manchmal wie ein Babel."}]},
