  "baboon": {label:"Pavian",gender:"der",plural:"Paviane", ex5:[{t:1,s:"Ein Pavian saß auf dem Felsen."},{t:2,s:"Der Pavian suchte nach etwas zu essen."},{t:3,s:"Paviane leben in großen Gruppen zusammen."},{t:4,s:"Ich habe im Zoo einen Pavian beobachtet."},{t:5,s:"Der Pavian ist ein faszinierendes Tier."}]},
  "baboons": {label:"Paviane",gender:"die",plural:"Paviane", ex5:[{t:1,s:"Wir sahen eine Gruppe von Pavianen am Fluss spielen."},{t:2,s:"Paviane sind für ihre komplexe soziale Struktur bekannt."},{t:3,s:"Der Fotograf machte Bilder von Pavianen in der Savanne."},{t:4,s:"Die Paviane suchen gemeinsam nach Nahrung."},{t:5,s:"Man kann Paviane oft in afrikanischen Nationalparks sehen."}]},
  "baby": {label:"Baby",gender:"das",plural:"Babys", ex5:[{t:1,s:"Das Baby hat geweint."},{t:2,s:"Das Baby ist sehr klein."},{t:3,s:"Wir haben das Baby auf den Arm genommen."},{t:4,s:"Das Baby schläft tief und fest."},{t:5,s:"Die Mutter hält ihr Baby liebevoll im Arm."}]},
  "babyhood": {label:"Kleinkindalter",gender:"das",plural:"—", ex5:[{t:1,s:"Sie erinnert sich an nichts aus ihrem Kleinkindalter."},{t:2,s:"Die Fotos zeigen ihn während seines glücklichen Kleinkindalters."},{t:3,s:"Ich habe einige alte Spielzeuge aus meinem Kleinkindalter auf dem Dachboden gefunden."},{t:4,s:"Das Kleinkindalter ist eine prägende Zeit."},{t:5,s:"Er hat keine Erinnerungen mehr an sein frühes Kleinkindalter."}]},
