  "baptist": {label:"Baptist",gender:"der",plural:"Baptisten", ex5:[{t:1,s:"Sie besucht jeden Sonntagmorgen eine Baptistenkirche."},{t:2,s:"Er wuchs in einer strengen Baptistenfamilie auf."},{t:3,s:"Die Baptisten organisierten eine Wohltätigkeitsveranstaltung."},{t:4,s:"Der Baptistenpastor hielt eine bewegende Predigt."},{t:5,s:"Er ist ein gläubiger Baptist."}]},
  "baptiste": {label:"Baptiste",gender:"",plural:"—", ex5:[{t:1,s:"Baptiste zieht nächste Woche in eine neue Wohnung."},{t:2,s:"Ich warte darauf, dass Baptiste am Bahnhof ankommt."},{t:3,s:"Baptiste spielt gerne abends Klavier."},{t:4,s:"Ich habe mit Baptiste über das Projekt gesprochen."},{t:5,s:"Baptiste ist ein guter Freund."}]},
