  "beautician": {label:"Kosmetikerin",gender:"die",plural:"Kosmetikerinnen", ex5:[{t:1,s:"Ich habe einen Termin bei meiner Lieblingskosmetikerin gemacht."},{t:2,s:"Die Kosmetikerin hat mir heute einen neuen Haarschnitt verpasst."},{t:3,s:"Sie hat hart gelernt, um eine lizenzierte Kosmetikerin zu werden."},{t:4,s:"Die Kosmetikerin gab mir gute Ratschläge."},{t:5,s:"Ich gehe regelmäßig zur Kosmetikerin."}]},
  "beauties": {label:"Schönheiten",gender:"die",plural:"Schönheiten", ex5:[{t:1,s:"Der Garten ist voller natürlicher Schönheiten."},{t:2,s:"Schau dir diese Blumen an, sie sind wahre Schönheiten."},{t:3,s:"Die Insel ist berühmt für ihre vielen natürlichen Schönheiten."},{t:4,s:"Das Museum zeigt verschiedene Schönheiten der Kunst."},{t:5,s:"Sie bewunderte die Schönheiten der Landschaft."}]},
  "beautification": {label:"Verschönerung",gender:"die",plural:"Verschönerungen", ex5:[{t:1,s:"Die Stadt hat ein neues Verschönerungsprojekt gestartet."},{t:2,s:"Blumen sind Teil der Verschönerung des Parks."},{t:3,s:"Wir brauchen mehr Verschönerung in unserer Nachbarschaft."},{t:4,s:"Die Verschönerung des Stadtzentrums ist geplant."},{t:5,s:"Die Verschönerung der Straßen ist wichtig."}]},
