  "blackened": {label:"geschwärzt",gender:"",plural:"—", ex5:[{t:1,s:"Der Toast war geschwärzt, weil ich ihn zu lange im Toaster ließ."},{t:2,s:"Er schrubbte die geschwärzte Pfanne, bis sie wieder sauber war."},{t:3,s:"Der Waldbrand hinterließ geschwärzte und kahle Bäume."},{t:4,s:"Die Ränder des Brotes sind geschwärzt."},{t:5,s:"Der Topfboden ist völlig geschwärzt."}]},
  "blacker": {label:"schwarzer",gender:"",plural:"—", ex5:[{t:1,s:"Die Nacht wurde immer schwarzer, als die Wolken den Mond verdeckten."},{t:2,s:"Diese Tinte ist schwarzer als die, die ich vorher benutzt habe."},{t:3,s:"Der Kaffee war mir zu stark und viel schwarzer als gewohnt."},{t:4,s:"Der Himmel sah kurz vor dem Sturm immer schwarzer aus."},{t:5,s:"Seine Jacke war schwarzer als die meines Bruders."}]},
  "blackest": {label:"schwärzester",gender:"",plural:"—", ex5:[{t:1,s:"Der Himmel nahm kurz vor dem Sturm die schwärzeste Farbe an."},{t:2,s:"Er trug den schwärzesten Anzug bei der Beerdigung."},{t:3,s:"Das war die schwärzeste Nacht, die ich je erlebt habe."},{t:4,s:"Diese Tinte ist die schwärzeste, die wir im Laden haben."},{t:5,s:"In der schwärzesten Stunde seines Lebens fand er Hilfe."}]},
  "blacking": {label:"das Schwärzen",gender:"das",plural:"—", ex5:[{t:1,s:"Er verbrachte den Nachmittag mit dem Schwärzen seiner Lederstiefel für die Parade."},{t:2,s:"Der Künstler war mit dem Schwärzen des Hintergrunds beschäftigt."},{t:3,s:"Das Schwärzen der Fenster hilft, den Raum im Sommer kühl zu halten."},{t:4,s:"Das Schwärzen von Dokumenten ist aus Datenschutzgründen wichtig."},{t:5,s:"Er widmete sich dem Schwärzen der alten Metallteile."}]},
  "blackjack": {label:"Blackjack",gender:"das",plural:"—", ex5:[{t:1,s:"Wir haben im Urlaub zum Spaß Blackjack gespielt."},{t:2,s:"Er ist sehr gut darin, beim Blackjack Karten zu zählen."},{t:3,s:"Der Dealer gab die Karten für eine Runde Blackjack aus."},{t:4,s:"Blackjack ist ein beliebtes Spiel im Casino."},{t:5,s:"Sie hat beim Blackjack heute viel Glück gehabt."}]},
  "blacklist": {label:"schwarze Liste",gender:"die",plural:"schwarze Listen", ex5:[{t:1,s:"Die Website hat mein Konto auf eine schwarze Liste gesetzt."},{t:2,s:"Er stand auf der schwarzen Liste, weil er zu viele Zahlungen versäumt hatte."},{t:3,s:"Ich möchte meinen Namen von der schwarzen Liste entfernen lassen."},{t:4,s:"Die Firma hat den unzuverlässigen Lieferanten auf die schwarze Liste gesetzt."},{t:5,s:"Man sollte nicht auf einer schwarzen Liste landen."}]},
  "blacklisted": {label:"schwarzgelistet",gender:"",plural:"—", ex5:[{t:1,s:"Der Spieler wurde wegen Betrugs schwarzgelistet."},{t:2,s:"Er fand heraus, dass er vom örtlichen Club schwarzgelistet worden war."},{t:3,s:"Viele Unternehmen haben den unzuverlässigen Lieferanten schwarzgelistet."},{t:4,s:"Er wurde aufgrund eines Fehlers schwarzgelistet."},{t:5,s:"Einmal schwarzgelistet, ist es schwer, wieder Vertrauen zu gewinnen."}]},
  "blackmail": {label:"Erpressung",gender:"die",plural:"Erpressungen", ex5:[{t:1,s:"Der Kriminelle versuchte, sie durch Erpressung um Geld zu bringen."},{t:2,s:"Er weigerte sich, der Erpressung nachzugeben."},{t:3,s:"Erpressung ist ein schweres Verbrechen, das zu einer Gefängnisstrafe führen kann."},{t:4,s:"Sie wurde Opfer einer Erpressung."},{t:5,s:"Erpressung ist ein hinterhältiges Mittel, um an Geld zu kommen."}]},
  "blackmailed": {label:"erpresst",gender:"",plural:"—", ex5:[{t:1,s:"Der Kriminelle erpresste den Geschäftsmann um eine große Geldsumme."},{t:2,s:"Er wurde wegen seiner geheimen Vergangenheit erpresst."},{t:3,s:"Sie weigerte sich, sich von ihrem ehemaligen Partner erpressen zu lassen."},{t:4,s:"Er wurde schon lange erpresst, bevor er zur Polizei ging."},{t:5,s:"Niemand sollte sich erpresst fühlen, wenn er Hilfe sucht."}]},
  "blackmailer": {label:"Erpresser",gender:"der",plural:"Erpresser", ex5:[{t:1,s:"Der Erpresser forderte eine hohe Summe."},{t:2,s:"Die Polizei hat den Erpresser verhaftet."},{t:3,s:"Der Erpresser drohte damit, das Geheimnis zu enthüllen."},{t:4,s:"Der Erpresser wurde schließlich gefasst."},{t:5,s:"Sie meldete den Erpresser sofort bei der Polizei."}]},
  "blackmailing": {label:"Erpressung",gender:"die",plural:"Erpressungen", ex5:[{t:1,s:"Er wurde wegen Erpressung seines Geschäftspartners verhaftet."},{t:2,s:"Die Erpressung von anderen ist ein schweres Verbrechen."},{t:3,s:"Sie weigerte sich, seiner ständigen Erpressung nachzugeben."},{t:4,s:"Die Polizei ermittelt wegen Erpressung."},{t:5,s:"Er lebt von der Erpressung seiner Opfer."}]},
  "blackness": {label:"Schwärze",gender:"die",plural:"—", ex5:[{t:1,s:"Der Raum war von völliger Schwärze erfüllt."},{t:2,s:"Sie starrte in die Schwärze des Nachthimmels."},{t:3,s:"Ein plötzlicher Stromausfall stürzte die Stadt in die Schwärze."},{t:4,s:"Er verlor sich in der Schwärze der Nacht."},{t:5,s:"Die Schwärze des Waldes wirkte unheimlich."}]},
  "blackout": {label:"Stromausfall",gender:"der",plural:"Stromausfälle", ex5:[{t:1,s:"Der Sturm verursachte einen massiven Stromausfall in unserer Nachbarschaft."},{t:2,s:"Während des Stromausfalls gestern Abend benutzten wir Kerzen."},{t:3,s:"Die ganze Stadt erlebte einen plötzlichen Stromausfall."},{t:4,s:"Bei einem Stromausfall bleibt alles dunkel."},{t:5,s:"Wir haben für einen Stromausfall immer Batterien parat."}]},
  "blackouts": {label:"Stromausfälle",gender:"die",plural:"Stromausfälle", ex5:[{t:1,s:"Heftige Sommerstürme verursachen in dieser Stadt oft Stromausfälle."},{t:2,s:"Wir hielten für den Fall unerwarteter Stromausfälle Kerzen bereit."},{t:3,s:"Die Stadt erlebte aufgrund des veralteten Stromnetzes mehrere Stromausfälle."},{t:4,s:"Häufige Stromausfälle sind im Sommer ein großes Problem."},{t:5,s:"Wir sind auf Stromausfälle gut vorbereitet."}]},
  "blackpool": {label:"Blackpool",gender:"",plural:"—", ex5:[{t:1,s:"Wir sind für unseren Sommerurlaub nach Blackpool gefahren."},{t:2,s:"Blackpool ist für seinen großen Freizeitpark bekannt."},{t:3,s:"Der Strand in Blackpool war heute sehr voll."},{t:4,s:"Viele Menschen besuchen Blackpool im Sommer."},{t:5,s:"Blackpool liegt an der englischen Küste."}]},
  "blacks": {label:"Schwarztöne",gender:"die",plural:"Schwarztöne", ex5:[{t:1,s:"Sie kombiniert gerne verschiedene Schwarztöne in ihrer Kleidung."},{t:2,s:"Der Künstler verwendet verschiedene Schwarztöne, um Tiefe zu erzeugen."},{t:3,s:"Manche Leute denken, alle Schwarztöne seien gleich, aber das stimmt nicht."},{t:4,s:"Das Bild besteht aus vielen feinen Schwarztönen."},{t:5,s:"Die verschiedenen Schwarztöne geben dem Werk Charakter."}]},
  "blacksmith": {label:"Schmied",gender:"der",plural:"Schmiede", ex5:[{t:1,s:"Der Schmied schmiedete ein Werkzeug aus Eisen."},{t:2,s:"Der Schmied erhitzte das Metall, bis es glühte."},{t:3,s:"Funken sprühten, während der Schmied arbeitete."},{t:4,s:"Der Schmied versteht sein Handwerk sehr gut."},{t:5,s:"Wir besuchten den Schmied in seiner Werkstatt."}]},
  "blacksmiths": {label:"Schmiede",gender:"die",plural:"Schmiede", ex5:[{t:1,s:"Früher fertigten Schmiede Werkzeuge für das ganze Dorf an."},{t:2,s:"Die Schmiede arbeiteten hart an ihren heißen Öfen."},{t:3,s:"Wir besuchten ein Museum, das zeigte, wie alte Schmiede arbeiteten."},{t:4,s:"In der Vergangenheit waren Schmiede sehr angesehene Handwerker."},{t:5,s:"Die Schmiede trafen sich, um ihre Techniken auszutauschen."}]},
