  "blaine": {label:"Blaine",gender:"",plural:"—", ex5:[{t:1,s:"Blaine arbeitet an einem neuen wissenschaftlichen Projekt."},{t:2,s:"Ich habe Blaine gestern in der Bibliothek getroffen."},{t:3,s:"Blaine möchte in der Zukunft Pilot werden."},{t:4,s:"Blaine hat mir heute geholfen."},{t:5,s:"Weißt du, ob Blaine heute kommt?"}]},
  "blair": {label:"Blair",gender:"",plural:"—", ex5:[{t:1,s:"Blair hat eine Rede über die Zukunft des Landes gehalten."},{t:2,s:"Ich habe ein Buch über die Jahre gelesen, in denen Blair im Amt war."},{t:3,s:"Blair ist ein häufiger Name in vielen englischsprachigen Ländern."},{t:4,s:"Blair hat heute eine wichtige Entscheidung getroffen."},{t:5,s:"Hast du von Blair gehört?"}]},
  "blake": {label:"Blake",gender:"",plural:"—", ex5:[{t:1,s:"Blake ist ein begabter Künstler, der Porträts malt."},{t:2,s:"Ich habe Blake heute Morgen beim Gassigehen mit seinem Hund gesehen."},{t:3,s:"Blake hat den ersten Preis beim Schreibwettbewerb gewonnen."},{t:4,s:"Blake zeichnet sehr gerne."},{t:5,s:"Das Bild von Blake hängt im Wohnzimmer."}]},
  "blame": {label:"beschuldigen",gender:"",plural:"—", ex5:[{t:1,s:"Man sollte nicht immer andere beschuldigen."},{t:2,s:"Warum versuchst du, mich zu beschuldigen?"},{t:3,s:"Ich möchte niemanden beschuldigen."},{t:4,s:"Die Leute beschuldigen sich gegenseitig bei jedem Fehler."},{t:5,s:"Es ist leicht, andere für das eigene Versagen zu beschuldigen."}]},
  "blamed": {label:"beschuldigt",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde zu Unrecht beschuldigt."},{t:2,s:"Der Fahrer wurde für den Unfall beschuldigt."},{t:3,s:"Sie haben das Wetter für die Verspätung beschuldigt."},{t:4,s:"Wurde er wirklich von allen beschuldigt?"},{t:5,s:"Ich habe mich nicht beschuldigt gefühlt."}]},
  "blameless": {label:"schuldlos",gender:"",plural:"—", ex5:[{t:1,s:"Die Untersuchung ergab, dass er völlig schuldlos war."},{t:2,s:"Sie führte ein schuldloses Leben und half vielen Nachbarn."},{t:3,s:"Niemand ist bei einem Streit völlig schuldlos."},{t:4,s:"Er ist absolut schuldlos an dieser Situation."},{t:5,s:"Sie blieb in dieser Angelegenheit völlig schuldlos."}]},
  "blames": {label:"beschuldigt",gender:"",plural:"—", ex5:[{t:1,s:"Er beschuldigt immer andere für seine eigenen Fehler."},{t:2,s:"Sie beschuldigt das schlechte Wetter für die abgesagte Reise."},{t:3,s:"Niemand beschuldigt dich, weil du eine Pause brauchst."},{t:4,s:"Er beschuldigt seine Kollegen bei jeder Gelegenheit."},{t:5,s:"Die Mutter beschuldigt das Kind für den zerbrochenen Teller."}]},
  "blaming": {label:"beschuldigend",gender:"",plural:"—", ex5:[{t:1,s:"Hör auf, andere für deine Fehler beschuldigend zu behandeln."},{t:2,s:"Sie ist dabei, das Wetter für ihre Verspätung beschuldigend anzuführen."},{t:3,s:"Ich bin nicht beschuldigend, ich suche nur nach einer Lösung."},{t:4,s:"Er schaute mich mit einem beschuldigenden Blick an."},{t:5,s:"Sie sprach in einem beschuldigenden Ton mit ihm."}]},
  "blanc": {label:"Weiß",gender:"das",plural:"—", ex5:[{t:1,s:"Der Künstler nutzte ein wenig Weiß, um das Bild aufzuhellen."},{t:2,s:"Die Farbe Weiß wirkt sehr sauber und elegant."},{t:3,s:"Sie trug ein wunderschönes Kleid in Weiß."},{t:4,s:"Weiß ist eine sehr klassische Farbe."},{t:5,s:"Er malte die Wand in einem hellen Weiß."}]},
  "blanca": {label:"Blanca",gender:"",plural:"—", ex5:[{t:1,s:"Blanca ist meine beste Freundin aus der Schulzeit."},{t:2,s:"Ich habe Blanca heute Morgen am Bahnhof getroffen."},{t:3,s:"Blanca hat uns zu ihrer Geburtstagsparty nächste Woche eingeladen."},{t:4,s:"Blanca spricht sehr gut Deutsch."},{t:5,s:"Ich freue mich darauf, Blanca bald wiederzusehen."}]},
  "blanch": {label:"blanchieren",gender:"",plural:"—", ex5:[{t:1,s:"Blanchiere das Gemüse kurz in kochendem Wasser."},{t:2,s:"Sie hat die Mandeln blanchiert, um die Haut zu entfernen."},{t:3,s:"Durch das Blanchieren bleiben die Bohnen leuchtend grün."},{t:4,s:"Man sollte den Spinat kurz blanchieren."},{t:5,s:"Er blanchiert die Tomaten, damit sie sich besser schälen lassen."}]},
  "blanchard": {label:"Blanchard",gender:"",plural:"—", ex5:[{t:1,s:"Professor Blanchard ist ein Experte für Wirtschaftswissenschaften."},{t:2,s:"Ich habe die Unterlagen zur Prüfung an Herrn Blanchard gesendet."},{t:3,s:"Die Forschungsarbeit wurde von Dr. Blanchard verfasst."},{t:4,s:"Blanchard hat eine interessante Theorie vorgestellt."},{t:5,s:"Wir arbeiten gemeinsam mit Blanchard an diesem Projekt."}]},
  "blanche": {label:"Blanche",gender:"",plural:"—", ex5:[{t:1,s:"Blanche ist meine beste Freundin aus der Schulzeit."},{t:2,s:"Ich habe Blanche heute Abend zu meiner Geburtstagsparty eingeladen."},{t:3,s:"Blanche spricht fließend Französisch und Englisch."},{t:4,s:"Blanche ist heute sehr beschäftigt."},{t:5,s:"Ich habe Blanche schon lange nicht mehr gesehen."}]},
  "blanco": {label:"Blanco",gender:"der",plural:"—", ex5:[{t:1,s:"Herr Blanco ist unser neuer Spanischlehrer."},{t:2,s:"Die Firma wurde von einem Mann namens Blanco gegründet."},{t:3,s:"Ich habe Frau Blanco heute im Gemeindezentrum getroffen."},{t:4,s:"Der Name Blanco ist spanischen Ursprungs."},{t:5,s:"Blanco ist ein häufiger Nachname in spanischsprachigen Ländern."}]},
  "bland": {label:"fade",gender:"",plural:"—", ex5:[{t:1,s:"Die Suppe ist fad."},{t:2,s:"Der Film war fad und langweilig."},{t:3,s:"Wir mieden fad schmeckendes Essen."},{t:4,s:"Seine Erzählung war fad und uninteressant."},{t:5,s:"Ein fad aussehendes Zimmer ist nicht gemütlich."}]},
  "blandishment": {label:"Schmeichelei",gender:"die",plural:"Schmeicheleien", ex5:[{t:1,s:"Er ignorierte die Schmeicheleien des Verkäufers."},{t:2,s:"Keine Schmeichelei konnte ihren Sinn ändern."},{t:3,s:"Das Angebot war in schmeichelnde Schmeichelei verpackt."},{t:4,s:"Sie war nicht empfänglich für Schmeicheleien."},{t:5,s:"Seine Worte waren voller Schmeicheleien."}]},
  "blank": {label:"leer",gender:"",plural:"—", ex5:[{t:1,s:"Die Seite ist leer."},{t:2,s:"Mein Kopf wurde leer, als die Lehrerin fragte."},{t:3,s:"Wir ließen es leer."},{t:4,s:"Bitte füllen Sie die leeren Felder aus."},{t:5,s:"Er starrte auf das leere Blatt."}]},
