  "bypassed": {label:"umgangen",gender:"",plural:"—", ex5:[{t:1,s:"Die neue Autobahn hat das überfüllte Stadtzentrum umgangen."},{t:2,s:"Er hat das Sicherheitssystem umgangen, indem er einen versteckten Eingang benutzte."},{t:3,s:"Das Bauprojekt hat die Altstadt umgangen."},{t:4,s:"Wir haben den Stau geschickt umgangen."},{t:5,s:"Er hat die Regeln absichtlich umgangen."}]},
