  "byproduct": {label:"Nebenprodukt",gender:"das",plural:"Nebenprodukte", ex5:[{t:1,s:"Wärme ist ein Nebenprodukt der chemischen Reaktion."},{t:2,s:"Das Unternehmen verkauft das Nebenprodukt an andere Industrien."},{t:3,s:"Umweltverschmutzung ist ein bedauerliches Nebenprodukt des industriellen Wachstums."},{t:4,s:"Bei der Herstellung dieses Stoffes entsteht ein wertvolles Nebenprodukt."},{t:5,s:"Manchmal sind unerwartete Entdeckungen ein Nebenprodukt der Forschung."}]},
  "byron": {label:"Byron",gender:"",plural:"—", ex5:[{t:1,s:"Byron war ein sehr talentierter Dichter."},{t:2,s:"Ich habe meine Katze nach dem berühmten Dichter Byron benannt."},{t:3,s:"Byron hat sich dieses Semester dem Kunstclub angeschlossen."},{t:4,s:"Kennst du die Gedichte von Lord Byron?"},{t:5,s:"Byron war eine wichtige Figur der Romantik."}]},
  "bystander": {label:"Zuschauer",gender:"der",plural:"Zuschauer", ex5:[{t:1,s:"Ein Zuschauer rief um Hilfe."},{t:2,s:"Mehrere Zuschauer sahen den Unfall."},{t:3,s:"Er war nur ein unschuldiger Zuschauer."},{t:4,s:"Die Polizei befragte die anwesenden Zuschauer."},{t:5,s:"Als bloßer Zuschauer kann man oft wenig tun."}]},
  "bystanders": {label:"Zuschauer",gender:"die",plural:"Zuschauer", ex5:[{t:1,s:"Die Zuschauer sahen das Unglück schockiert an."},{t:2,s:"Ein Zuschauer rief die Notrufnummer an."},{t:3,s:"Die Polizei befragte die Zuschauer nach ihren Aussagen."},{t:4,s:"Viele Zuschauer blieben stehen und beobachteten die Szene."},{t:5,s:"Als Zeugen wurden die Zuschauer gebeten, im Gebäude zu bleiben."}]},
  "byte": {label:"Byte",gender:"das",plural:"Bytes", ex5:[{t:1,s:"Diese Datei ist nur wenige Bytes groß."},{t:2,s:"Computer verarbeiten Daten in Einheiten von einem Byte."},{t:3,s:"Ein Kilobyte entspricht 1024 Bytes."},{t:4,s:"Die Dateigröße wird in Bytes angegeben."},{t:5,s:"Jedes Byte speichert eine bestimmte Information."}]},
  "bytes": {label:"Bytes",gender:"die",plural:"Bytes", ex5:[{t:1,s:"Diese Dateigröße beträgt nur wenige Bytes."},{t:2,s:"Computer speichern Informationen in Bytes."},{t:3,s:"Die Bilddaten bestehen aus Millionen von Bytes."},{t:4,s:"Wir müssen die Anzahl der Bytes für diese Übertragung berechnen."},{t:5,s:"Die Festplatte hat eine Kapazität von vielen Gigabytes, was Tausenden von Millionen von Bytes entspricht."}]},
  "byzantine": {label:"byzantinisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Museum besitzt eine schöne Sammlung byzantinischer Kunst."},{t:2,s:"Wir haben im Unterricht die Geschichte des Byzantinischen Reiches studiert."},{t:3,s:"Die Kirche weist eine beeindruckende byzantinische Architektur auf."},{t:4,s:"Die byzantinische Kunst ist bekannt für ihre leuchtenden Farben."},{t:5,s:"Seine Kleidung hatte einen byzantinischen Stil."}]},
  "byzantium": {label:"Byzanz",gender:"das",plural:"—", ex5:[{t:1,s:"Byzanz war eine sehr wichtige Stadt in der antiken Geschichte."},{t:2,s:"Wir studieren den Aufstieg und Fall von Byzanz."},{t:3,s:"Das Reich hatte seine Wurzeln in der Stadt Byzanz."},{t:4,s:"Byzanz wurde später zu Konstantinopel."},{t:5,s:"Die Geschichte von Byzanz ist faszinierend."}]},
  "cab": {label:"Taxi",gender:"das",plural:"Taxis", ex5:[{t:1,s:"Das Taxi hielt an."},{t:2,s:"Das Taxi ist gelb."},{t:3,s:"Wir winkten ein Taxi heran."},{t:4,s:"Wir nahmen ein Taxi zum Hotel."},{t:5,s:"Kannst du bitte ein Taxi für uns rufen?"}]},
  "cabal": {label:"Klüngel",gender:"der",plural:"Klüngel", ex5:[{t:1,s:"Ein geheimer Klüngel plante den Putsch."},{t:2,s:"Sie fürchteten einen verborgenen Klüngel."},{t:3,s:"Der Klüngel kontrollierte die Abstimmung."},{t:4,s:"Es gab Gerüchte über einen geheimen Klüngel im Unternehmen."},{t:5,s:"Sie versuchten, einen Klüngel zu bilden, um ihre Ziele zu erreichen."}]},
  "cabana": {label:"Badehäuschen",gender:"das",plural:"Badehäuschen", ex5:[{t:1,s:"Wir mieteten ein privates Badehäuschen am Pool."},{t:2,s:"Das Hotel bietet ein Luxus-Badehäuschen für seine Gäste an."},{t:3,s:"Sie entspannte sich im Badehäuschen, während sie ein Buch las."},{t:4,s:"Das Badehäuschen bot Schutz vor der Sonne."},{t:5,s:"Am Strand gab es kleine Badehäuschen zum Mieten."}]},
  "cabaret": {label:"Kabarett",gender:"das",plural:"Kabaretts", ex5:[{t:1,s:"Wir sahen uns eine musikalische Show im örtlichen Kabarett an."},{t:2,s:"Das Kabarett war voller Musik und Lachen."},{t:3,s:"Sie träumt davon, auf einer Kabarettbühne aufzutreten."},{t:4,s:"Das Kabarett bot eine Mischung aus Gesang und Comedy."},{t:5,s:"Wir besuchten ein bekanntes Kabarett in der Stadt."}]},
