  "cacophony": {label:"Kakophonie",gender:"die",plural:"Kakophonien", ex5:[{t:1,s:"Das Aufwärmen des Orchesters war eine Kakophonie aus misstönenden Klängen."},{t:2,s:"Eine Kakophonie von Autohupen erfüllte die Kreuzung."},{t:3,s:"Der Markt war eine Kakophonie aus rufenden Händlern."},{t:4,s:"Es herrschte eine Kakophonie der Stimmen im Saal."},{t:5,s:"Das Ergebnis war eine schreckliche Kakophonie."}]},
  "cactus": {label:"Kaktus",gender:"der",plural:"Kakteen", ex5:[{t:1,s:"Der Kaktus hat geblüht."},{t:2,s:"Dieser Kaktus ist sehr stachelig."},{t:3,s:"Ich habe den Kaktus gegossen."},{t:4,s:"Kakteen brauchen nur wenig Wasser."},{t:5,s:"Mein Kaktus steht auf der Fensterbank."}]},
  "cadaver": {label:"Leiche",gender:"die",plural:"Leichen", ex5:[{t:1,s:"Die Medizinstudenten untersuchten die Leiche im Labor."},{t:2,s:"Die Forscher untersuchten die Leiche, um die Todesursache zu klären."},{t:3,s:"Der Umgang mit einer Leiche erfordert großen Respekt."},{t:4,s:"Die Polizei fand die Leiche im Wald."},{t:5,s:"Die Leiche wurde für die Autopsie vorbereitet."}]},
