  "cade": {label:"Cade",gender:"",plural:"—", ex5:[{t:1,s:"Cade ist mein bester Freund in der Schule."},{t:2,s:"Ich gehe heute mit Cade in die Bibliothek."},{t:3,s:"Cade spielt nach dem Unterricht gerne Fußball."},{t:4,s:"Hast du Cade schon von unserem Plan erzählt?"},{t:5,s:"Cade ist ein sehr guter Zuhörer."}]},
  "cadence": {label:"Kadenz",gender:"die",plural:"Kadenzen", ex5:[{t:1,s:"Ihre Sprache hatte eine sanfte Kadenz."},{t:2,s:"Der Marsch behielt eine stetige Kadenz bei."},{t:3,s:"Er las das Gedicht mit einer langsamen Kadenz."},{t:4,s:"Die Kadenz seiner Stimme war beruhigend."},{t:5,s:"Die Musik änderte ihre Kadenz am Ende des Stücks."}]},
  "cadenza": {label:"Kadenz",gender:"die",plural:"Kadenzen", ex5:[{t:1,s:"Die Solistin brillierte mit einer atemberaubenden **Kadenz**."},{t:2,s:"Eine **Kadenz** gibt dem Solisten die Möglichkeit, sein Können zu zeigen."},{t:3,s:"Sie improvisierte die **Kadenz** wunderschön."},{t:4,s:"Die **Kadenz** am Ende des Konzerts war sehr beeindruckend."},{t:5,s:"Diese **Kadenz** ist technisch sehr anspruchsvoll."}]},
  "cadet": {label:"Kadett",gender:"der",plural:"Kadetten", ex5:[{t:1,s:"Der **Kadett** stand während der Zeremonie stramm."},{t:2,s:"Jeder **Kadett** muss die strengen Regeln der Akademie befolgen."},{t:3,s:"Der junge **Kadett** träumt davon, ein großer Pilot zu werden."},{t:4,s:"Als **Kadett** lernte er Disziplin und Gehorsam."},{t:5,s:"Der **Kadett** absolvierte seine Ausbildung mit Auszeichnung."}]},
  "cadets": {label:"Kadetten",gender:"die",plural:"—", ex5:[{t:1,s:"Die **Kadetten** marschieren in der Parade."},{t:2,s:"Neue **Kadetten** müssen ein strenges körperliches Training durchlaufen."},{t:3,s:"Die **Kadetten** salutierten ihrem Kommandanten."},{t:4,s:"Die **Kadetten** bereiten sich auf ihre zukünftigen Aufgaben vor."},{t:5,s:"Eine Gruppe von **Kadetten** besuchte das Museum."}]},
  "cadillac": {label:"Cadillac",gender:"der",plural:"Cadillacs", ex5:[{t:1,s:"Er träumt davon, eines Tages einen Oldtimer-**Cadillac** zu fahren."},{t:2,s:"Der **Cadillac**, der vor dem Gebäude parkt, sieht teuer aus."},{t:3,s:"Mein Großvater besaß früher einen klassischen **Cadillac**."},{t:4,s:"Der **Cadillac** ist bekannt für seinen Komfort und Luxus."},{t:5,s:"Wir sahen einen wunderschönen roten **Cadillac** auf der Straße."}]},
  "cadmium": {label:"Cadmium",gender:"das",plural:"—", ex5:[{t:1,s:"**Cadmium** ist ein toxisches Schwermetall."},{t:2,s:"**Cadmium** wird in einigen Batterien verwendet."},{t:3,s:"Die Farbe enthielt Spuren von **Cadmium**."},{t:4,s:"**Cadmium** kann schädlich für die menschliche Gesundheit sein."},{t:5,s:"Die Entsorgung von **Cadmium** muss sorgfältig erfolgen."}]},
  "cadre": {label:"Kader",gender:"der",plural:"Kader", ex5:[{t:1,s:"Ein kleiner **Kader** von Offizieren plante die gesamte Operation."},{t:2,s:"Die Partei verließ sich auf einen loyalen **Kader** von Organisatoren."},{t:3,s:"Sie trat dem Elite-**Kader** der leitenden Forscher bei."},{t:4,s:"Der **Kader** der Mitarbeiter wurde erweitert."},{t:5,s:"Er gehört zum festen **Kader** des Unternehmens."}]},
  "cadres": {label:"Kader",gender:"die",plural:"—", ex5:[{t:1,s:"Die Partei bildete eine neue Gruppe junger **Kader** aus."},{t:2,s:"Erfahrene **Kader** sind für das Wachstum des Unternehmens unerlässlich."},{t:3,s:"Die Organisation verlässt sich auf ihre loyalen **Kader**, um das Team zu führen."},{t:4,s:"Die **Kader** trafen sich zur jährlichen Konferenz."},{t:5,s:"Es wurden neue **Kader** in Führungspositionen befördert."}]},
  "caesar": {label:"Caesar",gender:"der",plural:"Caesaren", ex5:[{t:1,s:"**Caesar** war ein mächtiger Anführer im alten Rom."},{t:2,s:"Das Stück schildert das Leben und den Tod **Caesars**."},{t:3,s:"Viele Historiker studieren die Militärkampagnen **Caesars**."},{t:4,s:"**Caesar** ist bekannt für seine Eroberung Galliens."},{t:5,s:"Die Geschichte von **Caesar** fasziniert bis heute."}]},
