  "carbonate": {label:"Karbonat",gender:"das",plural:"Karbonate", ex5:[{t:1,s:"Calciumkarbonat ist eine häufige Substanz in Gesteinen."},{t:2,s:"Das Experiment erfordert, dass wir das Karbonat in der Probe identifizieren."},{t:3,s:"Wir haben im Chemieunterricht gelernt, wie man Wasser mit Kohlensäure versetzt."},{t:4,s:"Das Karbonat löst sich in der Säure auf."},{t:5,s:"Viele Mineralien bestehen aus Karbonat."}]},
  "carbonated": {label:"kohlensäurehaltig",gender:"",plural:"—", ex5:[{t:1,s:"Ich trinke lieber stilles Wasser als kohlensäurehaltige Getränke."},{t:2,s:"Dieses Mineralwasser ist von Natur aus kohlensäurehaltig."},{t:3,s:"Zu viele kohlensäurehaltige Limonaden können den Zähnen schaden."},{t:4,s:"Möchtest du ein kohlensäurehaltiges Wasser oder lieber stilles?"},{t:5,s:"Das kohlensäurehaltige Getränk erfrischt mich an heißen Tagen."}]},
  "carboniferous": {label:"karbonisch",gender:"",plural:"—", ex5:[{t:1,s:"Das karbonische Zeitalter ist für seine riesigen Sumpfwälder bekannt."},{t:2,s:"Viele Kohlevorkommen stammen aus der karbonischen Periode."},{t:3,s:"Im karbonischen Zeitalter lebten riesige Insekten."},{t:4,s:"Die karbonische Zeit war für die Entwicklung der Pflanzen wichtig."},{t:5,s:"Wir untersuchten die karbonischen Gesteinsschichten im Labor."}]},
  "carbonyl": {label:"Carbonyl",gender:"das",plural:"Carbonyle", ex5:[{t:1,s:"Die Carbonylgruppe ist in der organischen Chemie essenziell."},{t:2,s:"Wir haben die Carbonylbindung mittels Spektroskopie identifiziert."},{t:3,s:"Carbonylverbindungen finden in industriellen Prozessen breite Anwendung."},{t:4,s:"Das Carbonyl ist ein zentraler Bestandteil vieler Moleküle."},{t:5,s:"Die Eigenschaften von Carbonyl werden im Chemieunterricht besprochen."}]},
  "carboxylic": {label:"carbonsauer",gender:"",plural:"—", ex5:[{t:1,s:"Essigsäure ist eine bekannte carbonsaure Verbindung."},{t:2,s:"Die chemische Reaktion involviert eine carbonsaure Gruppe."},{t:3,s:"Die Studenten analysierten die Eigenschaften carbonsaurer Verbindungen."},{t:4,s:"Die carbonsaure Struktur ist für die Säurestärke wichtig."},{t:5,s:"Wir untersuchten das carbonsaure Milieu im Reagenzglas."}]},
  "carbs": {label:"Kohlenhydrate",gender:"die",plural:"Kohlenhydrate", ex5:[{t:1,s:"Ich versuche in letzter Zeit, weniger Kohlenhydrate zu essen."},{t:2,s:"Diese Diät vermeidet zu viele Kohlenhydrate."},{t:3,s:"Nudeln sind voller Kohlenhydrate."},{t:4,s:"Kohlenhydrate liefern dem Körper wichtige Energie."},{t:5,s:"Man sollte auf eine ausgewogene Zufuhr von Kohlenhydraten achten."}]},
