  "carcass": {label:"Kadaver",gender:"der",plural:"Kadaver", ex5:[{t:1,s:"Der Löwe überließ den Kadaver den Geiern."},{t:2,s:"Sie fanden den Kadaver eines Hirsches im Wald."},{t:3,s:"Der Metzger bereitete den Kadaver für die Verarbeitung vor."},{t:4,s:"Der Kadaver lag am Straßenrand."},{t:5,s:"Man sollte den Kadaver aus hygienischen Gründen entfernen."}]},
  "carcasses": {label:"Kadaver",gender:"der",plural:"Kadaver", ex5:[{t:1,s:"Die Geier fraßen die tierischen Kadaver."},{t:2,s:"Der Forscher untersuchte die im Wald gefundenen Kadaver."},{t:3,s:"Es ist wichtig, die Kadaver aus hygienischen Gründen zu entfernen."},{t:4,s:"Überall lagen Kadaver auf dem Feld."},{t:5,s:"Die Kadaver wurden zur Untersuchung ins Labor gebracht."}]},
  "carcinogen": {label:"Karzinogen",gender:"das",plural:"Karzinogene", ex5:[{t:1,s:"Tabakrauch enthält so manches Karzinogen."},{t:2,s:"Die Chemikalie wurde als bekanntes Karzinogen verboten."},{t:3,s:"Forscher testen Substanzen auf ihre Wirkung als Karzinogen."},{t:4,s:"Man sollte den Kontakt mit jedem Karzinogen vermeiden."},{t:5,s:"Das Karzinogen wurde in dem Labor isoliert."}]},
